import React, {Component} from "react";
import hexRgb from "hex-rgb";
import {groupBy} from "lodash";

import ZONES_JSON from './data/zones.json'
import CHARTS_JSON from './data/charts.json'
import POI_JSON from './data/poi_v4.json'
import POI_TYPES_JSON from './data/poi_types.json'
import REGIONS_JSON from './data/regions.json'
import COMMUNES_JSON from './data/communes.json'
import SUB_COMMUNES_JSON from './data/sub_communes.json'

import Map from "./components/Map/Map";
import Nav from "./components/Nav/Nav";
import Sidebar from "./components/Sidebar/Sidebar";

import MultiSelect from "./components/MultSelect/MultiSelect";

import "./scss/main.scss";

function hexToArr(hex) {
  const arr = hexRgb(hex, {format: "array"});
  arr.pop();
  return arr;
}

const COLORS = [
  hexToArr("#d3ecf0"),
  hexToArr("#42d4e6"),
  hexToArr("#49bf9f"),
  hexToArr("#fffaac"),
  hexToArr("#ff9992"),
  hexToArr("#ff5e52"),
  hexToArr("#836bff"),
  hexToArr("#c040d7"),
  hexToArr("#d3ecf0"),
  hexToArr("#d3ecf0"),
  hexToArr("#d3ecf0")
];

const CHART_COLORS = [
  hexToArr("#49bf9f"),
  hexToArr("#fffaac"),
  hexToArr("#ff5e52"),
  hexToArr("#836bff"),
  hexToArr("#c040d7")
];

const CONVERT_OPERATOR = {
  divide: function (x, y) {
    return x / y;
  }
};

class App extends Component {
  constructor(props) {
    super(props);
    this.state = {
      zones: {
        active: {},
        items: []
      },
      layer: {},
      legend: {}
    };

    this._selectZone = this._selectZone.bind(this);
    this._storeData = this._storeData.bind(this);
    this._clickedNav = this._clickedNav.bind(this);
    this._filterPoints = this._filterPoints.bind(this);
  }

  _selectZone(zone) {
    const zones = this.state.zones;
    zones.active = zone;
    this.setState({zones});
  }

  _clickedNav(layer) {
    console.log(layer)
    this.setState({layer});
  }

  _filterPoints(points) {
    const {layer, zones} = this.state;

    const filtered = points
      ? points
        .filter(item => {
          if (layer.id && layer.id === item.groupid) {
            return true;
          }
          if (!layer.id) {
            return true;
          }
        })
        .filter(item => {
          const {active, id} = zones.active;

          const activeZones =
            active && active.length ? active.map(item => item.id) : null;

          if (activeZones) {
            return activeZones.includes(item[id.toString()]);
          }

          return true;
        })
      : null;

    return filtered || [];
  }

  _createLegend() {
    const {layer, types} = this.state;
    if (layer.id && layer.items) {
      return layer.items.map(item => {
        return {
          id: item.id,
          label: item.label,
          color: COLORS[item.typecolor]
        };
      });
    } else if (types && !layer.id) {
      return types.map(item => {
        return {
          id: item.id,
          label: item.label,
          color: COLORS[item.groupcolor]
        };
      });
    }
  }

  _createCharts() {
    const {zones, layer, points, charts} = this.state;

    let items = [];

    if (zones.active.id) {
      if (zones.active.active && zones.active.active.length) {
        items = zones.active.active;
      }
    }

    let min, max;

    return {
      label: zones.active.id ? zones.active.label : " ",
      items: charts
        ? charts
          .filter(chart => chart.groupid === layer.id)
          .map((chart, i) => {
            return {
              id: chart.id,
              label: chart.label,
              type: chart.type,
              data: {
                min: Number(chart.min),
                max: Number(chart.max),
                unit: chart.unit,
                values: items.map((item, i) => {
                  return {
                    value: item[chart.id + ".value"],
                    population: item[chart.id + ".population"],
                    color: CHART_COLORS[i],
                    label: item.label
                  };
                })
              }
            };
          })
        : []
    };
  }

  _storeData(zones, points, types, charts) {
    this.setState({zones, points, types, charts});
  }

  async componentDidMount() {
    try {
      const zones = ZONES_JSON

      const poi = POI_JSON

      const types = POI_TYPES_JSON

      const charts = CHARTS_JSON

      zones[0].items = REGIONS_JSON.map(item => {
        item.value = item.id;
        return item
      })

      zones[1].items = COMMUNES_JSON.map(item => {
        item.value = item.id;
        return item
      })

      zones[2].items = SUB_COMMUNES_JSON.map(item => {
        item.value = item.id;
        return item
      })

      const points = poi.map(item => {
        const match = types.find(type => {
          return type.id === item.typeid;
        });

        item.groupcolor = COLORS[match.groupcolor];
        item.typecolor = COLORS[match.typecolor];
        return item;
      });

      const groups = groupBy(types, "groupid");

      const nav = Object.keys(groups).map((key, i) => {
        return {
          id: groups[key][0].groupid,
          value: groups[key][0].groupid,
          label: groups[key][0].grouplabel,
          groupcolor: groups[key][0].groupcolor,
          items: groups[key],
          disabled: groups[key][0].hidden === "TRUE" ? true : false
        };
      });

      this._storeData(
        {
          active: {},
          items: zones
        },
        points,
        nav,
        charts
      );
    } catch (e) {
      console.log(e);
    }
  }

  render() {
    const {layer, zones, points, types} = this.state;

    const demographics = zones.active.items || [];

    return (
      <div className="App">
        <header className="App__header">
          <MultiSelect
            selected={zones.active}
            options={zones.items}
            onChange={this._selectZone}
          />
        </header>
        <main>
          <Nav types={types} active={layer} clicked={this._clickedNav}/>
          <Map
            data={zones.active}
            layer={layer}
            points={this._filterPoints(points)}
            legend={this._createLegend()}
          ></Map>
          <Sidebar charts={this._createCharts()} demographics={demographics}/>
        </main>
      </div>
    );
  }
}

export default App;
